package main

import (
	"bytes"
	"fmt"
	"io"
)

// Save accepts an interface, so any writer works.
func Save(w io.Writer, data string) error {
	_, err := io.WriteString(w, data)
	return err
}

func main() {
	var buf bytes.Buffer
	Save(&buf, "log entry") // pass a *bytes.Buffer
	fmt.Println(buf.String())
	// Output: log entry
}

package main

import "fmt"

type Incer interface{ Inc() }

type Counter struct{ n int }

func (c *Counter) Inc() { c.n++ } // pointer receiver

func main() {
	c := Counter{}
	var i Incer = &c // must be &c; c alone would not compile
	i.Inc()
	fmt.Println(c.n)
	// Output: 1
}

