package solution

import "math"

// Shape is the behavioral contract: anything with an area.
type Shape interface {
	Area() float64
}

type Rectangle struct{ W, H float64 }

func (r Rectangle) Area() float64 { return r.W * r.H } // satisfies Shape

type Circle struct{ R float64 }

func (c Circle) Area() float64 { return math.Pi * c.R * c.R } // satisfies Shape

// Solve accepts the interface, so it works for any current or future Shape.
func Solve(shapes []Shape) float64 {
	total := 0.0
	for _, s := range shapes {
		total += s.Area() // dynamic dispatch to the concrete type
	}
	return total
}

